package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NonMonotonousSequenceException;
import org.apache.commons.math.exception.util.Localizable;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.equals(double x, double y)
 * Designed to maximize branch and line coverage.
 */
public class MathUtils_equals_TriageGen5Test {









    @Test
    public void testEquals_Infinity() {
        // Covers: x == y -> true for Infinity
        assertTrue("Should return true for positive infinity", 
            MathUtils.equals(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY));
        assertTrue("Should return true for negative infinity", 
            MathUtils.equals(Double.NEGATIVE_INFINITY, Double.NEGATIVE_INFINITY));
        assertFalse("Should return false for mixed infinities", 
            MathUtils.equals(Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY));
    }
}
